const inputData = $input.item.json || {};
const query = inputData.query || {};
const body = inputData.body || inputData;

const title = body.title || query.title || "Learning to Breathe";
const customText = body.custom_text || query.custom_text || "you don't have to carry the weight of everything - because some things were never meant to be held ... and when you feel tired in a world that never stops - remember that healing is just learning to breathe ... so let your heavy thoughts rest - tomorrow will be kinder";
const category = body.category || query.category || "Solitude & Healing";
const promptIds = body.prompt_ids || query.prompt_ids || [6, 7, 8, 9, 10];

return {
  json: {
    engine: "google_flow_and_qwen_0.6",
    voice_engine: "qwen_0.6_whisper_cloned",
    title: title,
    category: category,
    custom_text: customText,
    prompt_ids: promptIds,
    job_id: `job_flow_qwen_${Date.now()}`,
    triggered_at: new Date().toISOString()
  }
};

const videoMeta = $input.item.json;
const files = videoMeta.files || {};

const formattedTags = Array.isArray(videoMeta.hashtags) 
  ? videoMeta.hashtags.join(' ') 
  : '#whisprs #poetry #quotes #deepthoughts #reels';

const fbReelsPayload = {
  page_id: 'WHISPRS_PAGE_ID_PLACEHOLDER',
  caption: `${videoMeta.hook}\n\n"${videoMeta.script}"\n\nFollow @Whisprs for quiet reminders and late-night thoughts. 🖤✨\n\n${formattedTags}`,
  video_url: videoMeta.stream_url,
  source_file: files.video_mp4
};

const ytShortsPayload = {
  snippet: {
    title: `${videoMeta.title} | Whisprs Poetry #Shorts`,
    description: `${videoMeta.caption}\n\n#shorts #poetry #whisprs #solitude`,
    tags: videoMeta.hashtags || ['whisprs', 'poetry', 'solitude', 'healing'],
    categoryId: '22'
  },
  status: {
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  }
};

return {
  json: {
    success: true,
    engine: 'google_flow_and_qwen_0.6',
    voice_engine: 'qwen_0.6_whisper_cloned',
    video_id: videoMeta.video_id,
    title: videoMeta.title,
    hook: videoMeta.hook,
    category: videoMeta.category,
    duration_seconds: videoMeta.duration_seconds,
    caption: videoMeta.caption,
    stream_url: videoMeta.stream_url,
    facebook_reels: fbReelsPayload,
    youtube_shorts: ytShortsPayload,
    status: 'READY_TO_PUBLISH'
  },
  binary: $input.item.binary
};
